import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/material.dart';
import '../../../services/personal_ai/reverse_marketplace_service.dart';
import '../../messenger/presentation/messenger_screen.dart';
class AurenReverseMarketplaceScreen extends StatefulWidget{const AurenReverseMarketplaceScreen({super.key});@override State<AurenReverseMarketplaceScreen> createState()=>_AurenReverseMarketplaceScreenState();}
class _AurenReverseMarketplaceScreenState extends State<AurenReverseMarketplaceScreen>{final s=ReverseMarketplaceService(),q=TextEditingController(),title=TextEditingController(),desc=TextEditingController(),price=TextEditingController();String cat='All',cur='USD';bool creating=false;
Future<void> _create()async{final uid=FirebaseAuth.instance.currentUser?.uid;if(uid==null||title.text.trim().isEmpty||desc.text.trim().isEmpty)return;final minor=price.text.trim().isEmpty?null:((double.tryParse(price.text.replaceAll(',','.'))??0)*100).round();await s.create(ownerId:uid,title:title.text,description:desc.text,category:cat=='All'?'General':cat,currency:cur,maxPriceMinor:minor);if(mounted){setState(()=>creating=false);title.clear();desc.clear();price.clear();ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تم نشر طلب الشراء للموردين.')));}}
@override void dispose(){for(final x in [q,title,desc,price])x.dispose();super.dispose();}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Reverse Marketplace')),body:ListView(padding:const EdgeInsets.all(16),children:[FilledButton.icon(onPressed:()=>setState(()=>creating=!creating),icon:const Icon(Icons.add),label:const Text('أريد شراء شيء — اطلب عروض الموردين')),if(creating)Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(children:[TextField(controller:title,decoration:const InputDecoration(labelText:'ماذا تريد؟')),TextField(controller:desc,maxLines:3,decoration:const InputDecoration(labelText:'المواصفات والكمية')),TextField(controller:price,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'الحد الأقصى للسعر (اختياري)')),DropdownButtonFormField<String>(value:cur,items:const ['USD','SDG','AED','SAR','EUR'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>cur=v??'USD')),const SizedBox(height:10),FilledButton(onPressed:_create,child:const Text('نشر الطلب'))]))),const SizedBox(height:10),TextField(controller:q,onChanged:(_)=>setState((){}),decoration:const InputDecoration(labelText:'ابحث في طلبات الشراء',prefixIcon:Icon(Icons.search),border:OutlineInputBorder())),const SizedBox(height:12),StreamBuilder<List<ReverseMarketplaceRequest>>(stream:s.watchOpen(query:q.text),builder:(c,x){if(!x.hasData)return const Center(child:CircularProgressIndicator());if(x.data!.isEmpty)return const Text('لا توجد طلبات شراء مفتوحة.');return Column(children:x.data!.map((r)=>Card(child:ListTile(title:Text(r.title),subtitle:Text(r.description),trailing:Text(r.maxPriceMinor==null?'بدون حد':'≤ '+((r.maxPriceMinor??0)/100).toStringAsFixed(2)+' '+r.currency),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>MessengerScreen(initialPrompt:'حلّل طلب الشراء هذا: '+r.title+'. التفاصيل: '+r.description+'. ساعدني في تجهيز عرض، ولا ترسل أي شيء بدون موافقتي.'))))).toList());})]));}